          try {
            await storage.createBomGuide(bom);
            bomCount++;
          } catch (error) {
            console.error('Failed to create BOM guide:', error);
          }
        }
      }

      res.json({ 
        inventoryCount, 
        transactionCount, 
        bomCount,
        message: "백업 복원 완료"
      });
    } catch (error) {
