      '유형': tx.type === 'inbound' ? '입고' : 
             tx.type === 'outbound' ? '출고' : 
             tx.type === 'move' ? '이동' : '조정',
      '제품코드': tx.itemCode,
      '품명': tx.itemName,
      '수량': tx.quantity,
      '출발지': tx.fromLocation || '',
      '목적지': tx.toLocation || '',
      '사유': tx.reason || '',
      '메모': tx.memo || '',
    }))
  );

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "입출고내역");
  XLSX.writeFile(wb, "입출고내역(분석전용).xlsx");
